  str_n25_idol_y_lesson_6 = "Illumina Broadcast No. 6: Calistenia",
  str_n25_idol_y_lesson_7 = "Esculturas de Hielo y Arquitectura de Castillos",
  str_n25_idol_y_lesson_8 = "Autoformación para genios",
  str_n25_idol_y_lesson_9 = "La extraña cocina de Roy",
  str_n25_idol_y_lesson_1_desc = "Interpretó “Los 300 versos de la noche blanca”. La luz de la luna brilla ante la ciudad... ¿Cómo va, de nuevo?",
  str_n25_idol_y_lesson_2_desc = "Interpretó \"No. 1 Princess of Rediesel\". Sinsa estaba tan conmovido por la actuación que lloró...",
  str_n25_idol_y_lesson_3_desc = "Interpretó \"La canción del mensajero\". ¡Apuesto a que cantar esto hace que sus entregas se sientan mucho más rápidas!",
  str_n25_idol_y_lesson_4_desc = "Realizó un baile de ballet. ¡Bailar de puntillas me hace parecer mucho más alta!",
  str_n25_idol_y_lesson_5_desc = "Realizó una demostración de tiro... ¿Pero eso realmente tiene algo que ver con el baile?",
  str_n25_idol_y_lesson_6_desc = "Realizó Illumina Broadcast Calisthenics No. 6, una rutina de ejercicios. ¡Uno dos tres CUATRO! ¡Estírate hacia abajo y toca los dedos de tus pies!",
  str_n25_idol_y_lesson_7_desc = "Hizo una escultura de hielo en forma de castillo. La nieve encima estaba hecha de azúcar glas, ¡así que comenzó a derretirse de inmediato!",
  str_n25_idol_y_lesson_8_desc = "Aprendió muchas técnicas de interpretación diferentes de Charon. ¡Él dice que todos los genios están solos!",
  str_n25_idol_y_lesson_9_desc = "Hizo muchas delicias desde cero... ¡Pero Zeta se comió la mayoría mientras no estábamos mirando!",
  str_n25_idol_y_lesson_2_learn = "Domina \"Princesa No. 1 de Rediesel\"",
  str_n25_idol_y_lesson_3_learn = "Domina \"La canción del mensajero\"",
  str_n25_idol_y_lesson_5_learn = "Artes de lucha dominadas",
  str_n25_idol_y_lesson_6_learn = "Mastered Illumina Broadcast Calisthenics No. 6",
  str_n25_idol_y_lesson_8_learn = "Domina las 108 habilidades para realizar",
  str_n25_idol_y_lesson_9_learn = "Domina las técnicas de cocina de Roy.",
  str_n25_idol_y_activity_title_1 = "Lanzamiento de nueva canción",
  str_n25_idol_y_activity_title_2 = "Álbum de fotos de lanzamiento",
  str_n25_idol_y_activity_title_3 = "Estrella en una obra de teatro",
  str_n25_idol_y_activity_title_4 = "Grabar un programa de radio",
  str_n25_idol_y_activity_title_5 = "Reunión de fans",
  str_n25_idol_y_activity_title_6 = "Dispara un anuncio de patrocinio",
  str_n25_idol_y_activity_desc_1 = "<color=#6d50c3>Lanzamiento de \"Lutumi Owl Lullaby\"</color>\nHoot, hoot ♪ Parece que muchos aurorianos escuchan esta canción antes de acostarse para dormir mejor.",
  str_n25_idol_y_activity_desc_2 = "<color=#6d50c3>Lanzado \"Sky-High Love\"</color>\nAmor en el cielo, siempre cuidándote ♪ ¡El Navegante se echó a llorar tan pronto como lo escuchó!",
  str_n25_idol_y_activity_desc_3 = "<color=#6d50c3>Lanzada \"Sonata del Chef\"</color>\nUsaron utensilios de cocina en lugar de instrumentos para grabar esta canción. ¡Parece que incluso mezclaron algunos ruidos de Eclipsite!",
  str_n25_idol_y_activity_desc_4 = "<color=#6d50c3>Álbum de fotos publicado: Fluff and Stuff!</color>\nUna colaboración entre Goldie y Novio con sus conejitos. ¡Los conejitos son demasiado lindos! ¿Quién no querría jugar con esos pequeños bichos todos los días?",
  str_n25_idol_y_activity_desc_5 = "<color=#6d50c3>Álbum de fotos publicado: Bunny Pyjamas</color>\nEste álbum está lleno de fotos de Goldie ¡en su pijama de conejita favorita! ¡Incluso a los comandantes de Illumina les encanta usarlos!",
  str_n25_idol_y_activity_desc_6 = "<color=#6d50c3>Álbum de fotos publicado: Train Hard, Idol!</color>\nEste álbum se compone de fotografías tomadas de Goldie durante el entrenamiento. ¡Cada minuto en el escenario requiere años de práctica! ¡Un verdadero ídolo nunca deja de entrenar!",
  str_n25_idol_y_activity_desc_7 = "<color=#6d50c3>Protagonizada por: \"Detective Golmes\"</color>\nUn gran éxito protagonizado Lilica como Liliarty, la mente maestra villana, y Goldie como detective Golmes. ¡El enfrentamiento final en Umbraton fue especialmente emocionante!",
  str_n25_idol_y_activity_desc_8 = "<color=#6d50c3>Protagonizada por: \"El fantasma del teatro\"</color>\n¡El debut de \"Phantom of the Theatre\" fue un gran éxito! Todo salió bien... Excepto por la parte donde Goldie rompió un montón de vasos con su falsete cantando. ¡Adivina que todo ese entrenamiento valió la pena!",
  str_n25_idol_y_activity_desc_9 = "<color=#6d50c3>Protagonizada por: \"Cinco mil metros por segundo\"</color>\n¡Esta versión de \"Five Thousand Meters Per Second\" se agotó por completo! Incluso lograste convertir el escenario en un tren, y Charon ¡Él mismo desempeñó el papel del conductor!",
  str_n25_idol_y_activity_desc_10 = "<color=#6d50c3>Programa de radio grabado: Idol Legends of Umbraton</color>\nGoldie interpretó a la protagonista femenina en una transmisión de radio de Idol Legends of Umbraton. El autor de la historia no desea ser nombrado, pero dice que es gerente en el Umbraton Guild.",
  str_n25_idol_y_activity_desc_11 = "<color=#6d50c3>Programa de radio grabado: Ada y el coloso</color>\nProtagonizó una producción de Ada and the Colossus para una estación de radio local. Aunque es bastante corta, la historia sigue siendo muy emotiva. Además, ¡a todos los niños les encanta!",
  str_n25_idol_y_activity_desc_12 = "<color=#6d50c3>Programa de radio grabado: Informe de tráfico de la ciudad de Gannon</color>\nApareció como estrella invitada en el informe de tráfico regular de Gannon City. ¡El sistema de transporte subterráneo de su ciudad es realmente complejo!",
  str_n25_idol_y_activity_desc_13 = "<color=#6d50c3>Organizó una reunión de fans: Umbraton</color>\n¡La fila para estrechar la mano de su amada estrella se extendía hasta las orillas del Río Dorado!",
  str_n25_idol_y_activity_desc_14 = "<color=#6d50c3>Organizó una reunión de fans: Rediesel Desert</color>\n¡Fue una sorpresa ver a todos en Rediesel Wrench formar una fila tan ordenada para el evento! Todo iba muy bien hasta que Barbara pidió un enfrentamiento de ídolos.",
  str_n25_idol_y_activity_desc_15 = "<color=#6d50c3>Organizó una reunión de fans: Illumina</color>\n¡Todos en Illumina están tan interesados en los ídolos ahora! Había tanta gente en el evento... ¡Aparentemente, incluso el Gran Mariscal apareció disfrazado para verificar las cosas!",
  str_n25_idol_y_activity_desc_16 = "<color=#6d50c3>Sesión de fotos completada: Rediesel Delights</color>\nDespués de tomar fotos promocionales para Rediesel Delights, una tienda de bocadillos local, ¡la tienda de Jomu ha estado llena durante días!",
  str_n25_idol_y_activity_desc_17 = "<color=#6d50c3>Sesión de fotos completada: Connolly's Cafe</color>\n¡Muchas personas querían probar el café de Connolly después de que se publicaron nuestras fotos promocionales! De hecho, está considerando contratar baristas a tiempo parcial...",
  str_n25_idol_y_activity_desc_18 = "<color=#6d50c3>Sesión de fotos completada: Northland</color>\nDespués de tomar fotos para promover el turismo de Northland, toneladas de visitantes viajaron allí para construir muñecos de nieve y disfrutar de las vistas.",
  str_n25_idol_y_activity_forwho_1 = "<color=#6d50c3>Lanzamiento de \"Lutumi Owl Lullaby\"</color>",
  str_n25_idol_y_activity_forwho_2 = "<color=#6d50c3>Lanzado \"Sky-High Love\"</color>",
  str_n25_idol_y_activity_forwho_3 = "<color=#6d50c3>Lanzada \"Sonata del Chef\"</color>",
  str_n25_idol_y_activity_forwho_4 = "<color=#6d50c3>Álbum de fotos publicado: Fluff and Stuff!</color>",
  str_n25_idol_y_activity_forwho_5 = "<color=#6d50c3>Álbum de fotos publicado: Bunny Pyjamas</color>",
  str_n25_idol_y_activity_forwho_6 = "<color=#6d50c3>Álbum de fotos publicado: Train Hard, Idol!</color>",
  str_n25_idol_y_activity_forwho_7 = "<color=#6d50c3>Protagonizada por: \"Detective Golmes\"</color>",
  str_n25_idol_y_activity_forwho_8 = "<color=#6d50c3>Protagonizada por: \"El fantasma del teatro\"</color>",
  str_n25_idol_y_activity_forwho_9 = "<color=#6d50c3>Protagonizada por: \"Cinco mil metros por segundo\"</color>",
  str_n25_idol_y_activity_forwho_10 = "<color=#6d50c3>Programa de radio grabado: Idol Legends of Umbraton</color>",
  str_n25_idol_y_activity_forwho_11 = "<color=#6d50c3>Programa de radio grabado: Ada y el coloso</color>",
  str_n25_idol_y_activity_forwho_12 = "<color=#6d50c3>Programa de radio grabado: Informe de tráfico de la ciudad de Gannon</color>",
  str_n25_idol_y_activity_forwho_13 = "<color=#6d50c3>Organizó una reunión de fans en: Umbraton</color>",
  str_n25_idol_y_activity_forwho_14 = "<color=#6d50c3>Organicé una reunión de fans en: Rediesel Desert</color>",
  str_n25_idol_y_activity_forwho_15 = "<color=#6d50c3>Organizó una reunión de fans en: Illumina</color>",
  str_n25_idol_y_activity_forwho_16 = "<color=#6d50c3>Sesión de fotos completada para: Rediesel Delights</color>",
  str_n25_idol_y_activity_forwho_17 = "<color=#6d50c3>Sesión de fotos completada para: Connolly's Cafe</color>",
  str_n25_idol_y_activity_forwho_18 = "<color=#6d50c3>Sesión de fotos completada para: Northland</color>",
  str_n25_idol_y_activity_desc_short_1 = "Hoot, hoot ♪ Parece que muchos aurorianos escuchan esta canción antes de acostarse para dormir mejor.",
  str_n25_idol_y_activity_desc_short_2 = "Amor sobre el cielo, siempre cuidándote ♪ ¡El Navegante se echó a llorar tan pronto como lo escuchó!",
  str_n25_idol_y_activity_desc_short_3 = "Usaron utensilios de cocina en lugar de instrumentos para grabar esta canción. ¡Parece que incluso mezclaron algunos ruidos de Eclipsite!",
  str_n25_idol_y_activity_desc_short_4 = "Una colaboración entre Goldie y Novio con sus conejitos. ¡Los conejitos son demasiado lindos! ¿Quién no querría jugar con esos pequeños bichos todos los días?",
  str_n25_idol_y_activity_desc_short_5 = "¡Este álbum está lleno de fotos de Goldie en su pijama de conejita favorita! ¡Incluso a los comandantes de Illumina les encanta usarlos!",
  str_n25_idol_y_activity_desc_short_6 = "Este álbum se compone de fotografías tomadas de Goldie durante el entrenamiento. ¡Cada minuto en el escenario requiere años de práctica! ¡Un verdadero ídolo nunca deja de entrenar!",
  str_n25_idol_y_activity_desc_short_7 = "Un gran éxito protagonizado por Lilica como Liliarty, la mente maestra villana, y Goldie como la Detective Golmes. ¡El enfrentamiento final en Umbraton fue una escena especialmente emocionante!",
  str_n25_idol_y_activity_desc_short_8 = "¡El debut de \"Phantom of the Theatre\" fue un gran éxito! Todo salió bien... Excepto por la parte donde Goldie rompió un montón de vasos con su falsete cantando. ¡Adivina que todo ese entrenamiento valió la pena!",
  str_n25_idol_y_activity_desc_short_9 = "¡Esta versión de \"Five Thousand Meters Per Second\" se agotó por completo! El escenario se convirtió en un tren, y Charon ¡Él mismo desempeñó el papel del conductor!",
  str_n25_idol_y_activity_desc_short_10 = "Goldie interpretó a la protagonista femenina en una transmisión de radio de Idol Legends of Umbraton. El autor de la historia no desea ser nombrado, pero dice que es gerente en el Umbraton Guild.",
  str_n25_idol_y_activity_desc_short_11 = "Protagonizó una producción de \"Ada and the Colossus\" para una estación de radio local. A pesar de que es bastante corto, la historia sigue siendo muy emotiva. Además, ¡a todos los niños les encanta!",
  str_n25_idol_y_activity_desc_short_12 = "Goldie fue una invitada especial en el informe de tráfico regular de Gannon City. ¡El sistema de transporte subterráneo de su ciudad es realmente complejo!",
  str_n25_idol_y_activity_desc_short_13 = "¡La fila para estrechar la mano de su amada estrella se extendía hasta las orillas del Río Dorado!",
  str_n25_idol_y_activity_desc_short_14 = "¡Fue una sorpresa ver a todos en Rediesel Wrench formar una fila tan ordenada para el evento! Todo iba muy bien hasta que Barbara pidió un enfrentamiento de ídolos.",
  str_n25_idol_y_activity_desc_short_15 = "¡Todos en Illumina están tan interesados en los ídolos ahora! Había tanta gente en el evento... ¡Aparentemente, incluso el Gran Mariscal apareció disfrazado para verificar las cosas!",
  str_n25_idol_y_activity_desc_short_16 = "Después de tomar las fotos promocionales para una tienda de bocadillos local llamada Rediesel Delights, ¡la gente ha estado agolpándose alrededor de la tienda de Jomu durante días!",
  str_n25_idol_y_activity_desc_short_17 = "¡Muchas personas querían probar el café de Connolly después de que se publicaron nuestras fotos promocionales! De hecho, está empezando a considerar contratar baristas a tiempo parcial...",
  str_n25_idol_y_activity_desc_short_18 = "Después de tomar fotos para promover el turismo en Northland, toneladas de visitantes viajaron allí para construir muñecos de nieve y disfrutar de las vistas.",
  str_n25_idol_y_trun_closed_14 = "¡El Concierto Debut fue un éxito! El Navigator continúa progresando constantemente en el camino para convertirse en un productor.\nPero con el Concierto de Debut llegando a su fin, el próximo desafío se acerca aún más: ¡el Concierto de Evaluación!\n¿Qué les depara el futuro? ¡Vuelve y continúa tu entrenamiento de ídolos para descubrirlo!",
  str_n25_idol_y_trun_closed_28 = "¡El Concurso de Evaluación fue un éxito! Goldie, Vice, Carleen, y el Navigator se toman un momento para celebrar su victoria ganada con tanto esfuerzo.\nTodo lo que queda ahora es el desafío final... ¡el Concierto de Graduación!\n¿Qué les depara el futuro? ¡Vuelve y continúa tu entrenamiento de ídolos para descubrirlo!",
  str_n25_idol_y_arrange_desc_1 = "<color=#4c4c4c>Vice</color> quiere conocerte.",
  str_n25_idol_y_arrange_desc_2 = "<color=#4c4c4c>Vice</color> quiere conocerte.",
