  str_n25_idol_game_intro_title = "Información de juego - Agencia Starlit",
  str_n25_idol_game_intro_head_1 = "Entrenamiento de ídolos",
  str_n25_idol_game_intro_head_2 = "Eventos de ídolos",
  str_n25_idol_game_intro_head_3 = "Conciertos",
  str_n25_idol_game_intro_body_1 = "Como productor, puedes ayudar Goldie mejora como ídolo eligiendo programas de entrenamiento adecuados en la interfaz de entrenamiento de ídolos.\nDurante el entrenamiento, puede encontrar momentos de Inspiración Súbita, ¡lo que puede impulsar significativamente el progreso de Goldie!\nAdemás, aparecerán diferentes Aurorianos en las distintas salas de entrenamiento de acuerdo con tu Lista de Tareas; ¡Hable con ellos y vea lo que tienen que ofrecer!\nEn ocasiones, aparecerá un paparazzi durante tus sesiones de entrenamiento; ¡recuerde rechazarlo con calma y cortesía!",
  str_n25_idol_game_intro_body_2 = "Organice eventos de ídolos para ganar más fanáticos.\nLos eventos de ídolos tienen diferentes requisitos de habilidad, ¡así que sigue entrenando para aumentar tus niveles de habilidad!",
  str_n25_idol_game_intro_body_3 = "¡Los conciertos son la mejor manera de mostrar las habilidades de un ídolo!\nPara organizar un concierto exitoso, debe ganar suficientes fanáticos antes de que se lleve a cabo, ¡o de lo contrario el concierto fracasará!\n¡Organiza más eventos de ídolos para aumentar tu base de fans!",
  str_n25_idol_game_puppy_btn = "Volver a entrenar",
  str_n25_idol_game_puppy_question_name = "Paparazzi",
  str_n25_idol_game_puppy_result_title = "Resultados",
  str_n25_idol_game_puppy_question_1 = "Hola, soy reportero del Daily Drivel. ¿Es cierto que la altura reportada de Goldie de 5'6'' es en realidad una mentira?",
  str_n25_idol_game_puppy_question_cond_1_1 = "¡Por supuesto que no! ¡Mide por ti mismo, si no me crees!",
  str_n25_idol_game_puppy_question_cond_1_2 = "¡Goldie realmente mide 5'6''!",
  str_n25_idol_game_puppy_question_cond_1_3 = "De cualquier manera, al menos es más alta que Vic.",
  str_n25_idol_game_puppy_result_1_1 = "Sacas una cinta métrica y mides la altura de Goldie... 5'6'', ¡ni más ni menos!",
  str_n25_idol_game_puppy_result_1_2 = "El reportero toma su respuesta poco convincente y se va.\nAl día siguiente, escribe sobre tu falta de pruebas.\nAlgunos de los fanáticos de Goldie comienzan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_result_1_3 = "El reportero publica un artículo con una comparación de altura de Goldie y Vic.\nEn eso, Vic es claramente más alto que ella.\nEl reportero afirma que estabas tratando de ridiculizar Vic.\nAlgunos de los fans de Goldie empiezan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_question_2 = "Hola, soy reportero del Daily Drivel. ¿Es cierto que la canción más nueva de Goldie fue plagiada de una canción de los Umbraton Boys?",
  str_n25_idol_game_puppy_question_cond_2_1 = "Esos rumores son completamente infundados. Incluso podemos contratar a un experto para resolver el asunto.",
  str_n25_idol_game_puppy_question_cond_2_2 = "No creo que las canciones suenen igual en absoluto...",
  str_n25_idol_game_puppy_question_cond_2_3 = "¿De qué Umbraton Boys estás hablando? ¡Ni siquiera he oído hablar de ellos!",
  str_n25_idol_game_puppy_result_2_1 = "Contratas a un famoso experto musical de Umbraton para que te brinde su opinión sobre el asunto.\nDespués de un extenso análisis...\nSe muestra que las dos canciones no tienen similitud alguna.",
  str_n25_idol_game_puppy_result_2_2 = [[
El reportero te acusa de hablar por prejuicios personales.
Algunos de los fans de Goldie empiezan a tener dudas sobre ella.]],
  str_n25_idol_game_puppy_result_2_3 = "El reportero te acusa de burlarte de los Umbraton Boys.\nAlgunos de los fanáticos de Goldie comienzan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_question_3 = "Hola, soy reportero del Daily Drivel. Circulan rumores de que Goldie usa una peluca en público y que, de hecho, es calva. ¿Te importaría comentar sobre esto?",
  str_n25_idol_game_puppy_question_cond_3_1 = "¡Pidámosle a un médico que aclare las cosas!",
  str_n25_idol_game_puppy_question_cond_3_2 = "¡Esto es discriminación contra los calvos y los calvos!",
  str_n25_idol_game_puppy_question_cond_3_3 = "Qué broma... ¿Por qué debería decirte algo?",
  str_n25_idol_game_puppy_result_3_1 = "Le pides a un médico que evalúe la salud del cuero cabelludo y el cabello de Goldie.\nEl médico asegura al público que el cabello de Goldie es perfectamente real y saludable.",
  str_n25_idol_game_puppy_result_3_2 = "Su respuesta solo hace que el reportero sospeche aún más.\nMuchos de los fanáticos de Goldie han comenzado a preocuparse por la salud de su cuero cabelludo.\nAlgunos de los fanáticos de Goldie comienzan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_result_3_3 = [[
El reportero te acusa y Goldie de ser arrogante.
Algunos de los fans de Goldie empiezan a tener dudas sobre ella.]],
  str_n25_idol_game_puppy_question_4 = "Hola, soy reportero del Daily Drivel. Se dice en la calle que Goldie en realidad no puede cantar y que todas sus actuaciones son de sincronización de labios. ¿Es esto cierto?",
  str_n25_idol_game_puppy_question_cond_4_1 = "¿Por qué no escuchas a Goldie cantar para ti?",
  str_n25_idol_game_puppy_question_cond_4_2 = "Ni siquiera podemos permitirnos artistas de doblaje profesionales como ese.",
  str_n25_idol_game_puppy_question_cond_4_3 = "¿Qué, estos rumores desvergonzados otra vez?",
  str_n25_idol_game_puppy_result_4_1 = "Usted pregunta Goldie cantar \"Solo para tus oídos\" al reportero.",
  str_n25_idol_game_puppy_result_4_2 = "El reportero te acusa de esquivar la pregunta.\nÉl escribe un artículo sobre tu vaga respuesta.\nAlgunos de los fans de Goldie empiezan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_result_4_3 = "El reportero lo acusa de calumniar a sus compañeros de la industria.\ny usted no tiene ninguna evidencia contundente.\nAlgunos de los fans de Goldie empiezan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_question_5 = "Hola, soy reportero del Daily Drivel. ¿Es cierto que Goldie ha estado manteniendo en secreto un Eclipsite como mascota?",
  str_n25_idol_game_puppy_question_cond_5_1 = "Eso parece ser un malentendido. La única mascota de Goldie es su cachorro.",
  str_n25_idol_game_puppy_question_cond_5_2 = "Si fuera cierto, Goldie ¡También podría tragarse su micrófono en el acto!",
  str_n25_idol_game_puppy_question_cond_5_3 = "Por favor, ¿es lo mejor que se te ocurre?",
  str_n25_idol_game_puppy_result_5_1 = [[
Llamas a Marshmallow,
quien felizmente rebota e inmediatamente gana al reportero.]],
  str_n25_idol_game_puppy_result_5_2 = "Debido a que el reportero no puede obtener la respuesta por la que vino,\ndecide difundir un nuevo rumor: Goldie le gusta comer cosas raras.\nAlgunos de los fanáticos de Goldie comienzan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_result_5_3 = "El reportero lo acusa de calumniar a sus compañeros de la industria.\ny usted no tiene ninguna evidencia contundente.\nAlgunos de los fans de Goldie empiezan a tener dudas sobre ella.",
  str_n25_idol_game_puppy_question_cond_disable = [[
