lo que significa que los rumores deben ser ciertos.
Algunos de los fans de Goldie empiezan a tener dudas sobre ella.]],
  str_n25_idol_game_spine_talk_name = "Goldie",
  str_n25_idol_game_spine_talk_1_1 = "¡Démoslo todo hoy, productor!",
  str_n25_idol_game_spine_talk_1_2 = "Con PlayerName como mi productor, ¡finalmente puedo concentrarme en mi entrenamiento!",
  str_n25_idol_game_spine_talk_1_3 = "¿Qué tipo de entrenamiento haremos hoy?",
  str_n25_idol_game_spine_talk_2_1 = "¡Espero que el concierto de evaluación también vaya bien!",
  str_n25_idol_game_spine_talk_2_2 = "¡La, la, la, laa! Debería ir más alto en esa última nota... ! ¡¿E-Estabas escuchando?!",
  str_n25_idol_game_spine_talk_2_3 = "¡Has estado haciendo un montón de progreso! ¡De eso puedo dar fe!",
  str_n25_idol_game_spine_talk_3_1 = "Te dejo el plan de entrenamiento de hoy, PlayerName!",
  str_n25_idol_game_spine_talk_3_2 = "¡La graduación no es el final, sino un nuevo comienzo! ¡Así que hagamos todo lo posible para organizar el mejor concierto de graduación de todos los tiempos!",
  str_n25_idol_game_spine_talk_3_3 = "¡Hola! ¡Ho! ¡Vamos! ...¿Eh? ¡Oh, solo te estoy animando!",
  str_n25_idol_game_spine_talk_concert_1_1 = "¡El concierto está a punto de comenzar! ¿Sintiéndose nervioso?",
  str_n25_idol_game_spine_talk_concert_1_2 = "¡Relajarse! ¡Contigo a mi lado, estoy seguro de que el concierto transcurrirá sin contratiempos!",
  str_n25_idol_game_spine_talk_concert_1_3 = "¿Quieres acariciar a Marshmallow? ¡Nada calma los nervios como acurrucarse con una linda criatura peluda!",
  str_n25_idol_game_spine_talk_concert_2_1 = "¡Mi productor y yo estamos tan listos como podemos para el concierto de evaluación! ¡Hagámoslo!",
  str_n25_idol_game_spine_talk_concert_2_2 = "Ya no pareces ni un poco nervioso, PlayerName! Eso significa que has recorrido un largo camino, ¿sabes?",
  str_n25_idol_game_spine_talk_concert_2_3 = "¡La horquilla para el cabello está apuntando hacia abajo! ¡Eso significa que algo bueno va a suceder!",
  str_n25_idol_game_spine_talk_concert_3_1 = "Finalmente, llegamos al concierto de graduación... Nunca podría haber logrado algo como esto sin su ayuda, PlayerName!",
  str_n25_idol_game_spine_talk_concert_3_2 = "¡Creo que escucho a la multitud llamándome para subir al escenario! Escuchar a tanta gente cantar mi nombre... ¡No puedo describir lo feliz que me hace sentir!",
  str_n25_idol_game_spine_talk_concert_3_3 = "Este será el mejor concierto de mi vida y te lo debo todo a ti. PlayerName! ¡Ahora es el momento de que mi productor se siente y me vea brillar!"
